import { adminContent, mountAdminContent } from './admin-console.js';
import { readMarketplace, sellerContext } from './marketplace-settings.js';
import { readDemoOrders, seedSellerExamples } from './order-storage.js';
import { mountOrderPanel } from './order-ui.js';
import { productEditorMarkup, mountProductEditor, pendingProductMarkup, sellerProductListMarkup, mountSellerProductList } from './product-editor.js';
import { hasSellerSession, endSellerSession, showSellerLogin } from './seller-login.js';
const seller=[['inicio','Visão geral'],['produtos','Produtos'],['novo-produto','Cadastrar produto'],['pedidos','Pedidos'],['logistica','Logística'],['financeiro','Financeiro'],['chat','Chat pós-compra'],['equipe','Equipe'],['classificacao','Classificação'],['aparencia','Vitrine da loja']];
const admin=[['inicio','Visão geral'],['sellers','Sellers'],['aprovacao','Aprovação de produtos'],['pedidos','Pedidos'],['financeiro','Financeiro'],['pagamentos','Pagamentos'],['logistica','Envio e retirada'],['cupons','Cupons e frete grátis'],['notificacoes','E-mail e WhatsApp'],['classificacao','Classificações'],['vitrines','Vitrines globais'],['regras','Regras'],['auditoria','Auditoria']];
const panel=(title,body)=>`<section class="portal-panel"><h2>${title}</h2>${body}</section>`;
const table=(heads,rows)=>`<div class="portal-table"><table><thead><tr>${heads.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const note=t=>`<div class="seller-note">${t}</div>`;
const empty=(title,text)=>panel(title,`<p>${text}</p>`);
function render(){const [raw='seller',requested='inicio',itemId]=(location.hash.slice(1)||window.__embeddedInitialHash||'seller').split('/');const role=raw==='admin'?'admin':'seller',isAdmin=role==='admin',menu=isAdmin?admin:seller.filter(([id])=>id!=='aparencia'||['official','indicated'].includes(readMarketplace().stores.find(s=>s.id===sellerContext())?.seal));if(!isAdmin&&!hasSellerSession()){showSellerLogin(render);return}if(!isAdmin)seedSellerExamples(readMarketplace().stores.find(s=>s.id===sellerContext())||readMarketplace().stores[0]);const page=requested==='editar-produto'?'editar-produto':menu.some(([id])=>id===requested)?requested:'inicio';const title=page==='editar-produto'?'Editar produto':menu.find(([id])=>id===page)[1];const link=(path,label)=>`<a class="text-link" href="#${role}/${path}">${label} →</a>`;let content='';
if(page==='inicio')content=`<div class="portal-cards">${(isAdmin?[['Sellers em análise','2','Cadastros demonstrativos'],['Revisões editoriais','3','Conteúdo aguardando análise'],['Ocorrências financeiras','0','Sem transações reais']]:[['Pedidos a preparar',String(readDemoOrders().flatMap(o=>o.suborders).filter(s=>s.store===sellerContext()&&['paid','preparing'].includes(s.status)).length),'Pedidos demonstrativos desta loja'],['Produtos de exemplo','3','Catálogo demonstrativo'],['Classificação','Oficial','Selo fictício da Casa Aurora']]).map(([a,b,c])=>`<article class="portal-card"><small>${a}</small><strong>${b}</strong><p>${c}</p></article>`).join('')}</div><div class="portal-cards">${(isAdmin?[['sellers','Conheça os novos lojistas','Analise cadastros e acompanhe a operação.'],['aprovacao','Cuide do catálogo','Revise títulos, descrições e imagens antes da publicação.'],['vitrines','Organize a experiência','Planeje os banners e vitrines do marketplace.']]:[['produtos','Seu catálogo, organizado','Gerencie a apresentação dos produtos da sua loja.'],['pedidos','Acompanhe suas vendas','Preparação, despacho e retirada em um só lugar.'],['aparencia','Sua loja com identidade','Conheça a estrutura de banners e vitrines.']]).map(([id,h,p])=>`<article class="portal-card"><h2>${h}</h2><p>${p}</p>${link(id,'Abrir '+h.toLowerCase())}</article>`).join('')}</div>`;
else if(page==='produtos')content=sellerProductListMarkup();else if(page==='novo-produto'||page==='editar-produto')content=productEditorMarkup();
else if(page==='pedidos')content='<div id="order-panel"></div>';
else if(page==='logistica')content=panel('Entrega e retirada',`<p>A loja define sua cobertura e tarifa. O tempo de transporte segue a regra única da plataforma.</p><form data-demo-form><div class="form-two"><label class="field-label">Valor demonstrativo por km (R$)<input class="panel-input" name="rate" type="number" min="0" step="0.01" value="2.50" required></label><label class="field-label">Distância máxima demonstrativa (km)<input class="panel-input" name="distance" type="number" min="0.1" step="0.1" value="10" required></label></div><label class="field-label">Horário de corte<input class="panel-input" type="time" value="15:00" required></label><p>Distância pelo trajeto nas ruas, com cálculo proporcional. Alterar o corte não adia pedidos existentes. Compras disponíveis 24 horas.</p><button class="btn" type="submit">Simular configuração</button><p class="form-status" role="status"></p></form>`);
else if(page==='financeiro')content=empty('Movimentações financeiras','Ainda não existem recebimentos ou repasses nesta demonstração.')+note('Comissão uniforme apenas sobre produtos. Frete destinado ao seller, sem comissão do marketplace. Taxa de pagamento descontada do seller por pedido. Provedor, taxas e prazos de repasse ainda serão definidos.');
else if(page==='chat')content='<div id="order-panel"></div>';
else if(page==='equipe')content=panel('Equipe da Casa Aurora',table(['Pessoa fictícia','Função','Escopo'],[['Marina Almeida','Responsável da loja','Própria empresa'],['Lucas Pereira','Operação','Pedidos e chat']]))+panel('Prévia de permissões individuais',`<form data-demo-form><div class="permission-grid">${['Produtos','Preços','Estoque','Pedidos','Chat','Financeiro','Editar aparência','Publicar aparência','Gerir equipe'].map(p=>`<label><input type="checkbox">${p}</label>`).join('')}</div><p style="margin:18px 0">A delegação precisa respeitar os acessos do autor e os limites da própria empresa.</p><button class="btn">Simular permissões</button><p class="form-status" role="status"></p></form>`);
else if(page==='classificacao')content=panel(isAdmin?'Classificações de lojas':'Classificação da Casa Aurora',table(['Loja fictícia','Classificação','Volume demonstrativo','Documentação'],(isAdmin?[['Casa Aurora','Oficial','201 pedidos em um dia','Validada — exemplo'],['Essencial Concept','Indicada','215 pedidos em um dia','Marca não validada'],['Verde & Vida','Comum','200 pedidos em um dia','Não analisada']]:[['Casa Aurora','Oficial','201 pedidos em um dia','Validada — exemplo']]))+`<p style="margin-top:18px">Mais de 200 pedidos em um único dia atendem ao volume. Oficial também exige validação dos documentos da empresa e da marca. Nenhum selo desta prévia foi concedido a uma empresa real.</p>`)+note('Documentos exigidos, status dos pedidos contados e validade/retirada dos selos ainda precisam de definição. Documentação privada não pertence à biblioteca pública de imagens.');
else if(page==='aparencia'||page==='vitrines')content=panel(isAdmin?'Composição da home global':'Página da loja · prévia da estrutura',`<p>${isAdmin?'Vitrines globais podem reunir produtos de diferentes lojas.':'Lojas Oficiais e Indicadas podem configurar a própria página. A Casa Aurora é uma loja Oficial fictícia.'}</p><div class="module-preview"><div>01 · Banner principal — desktop e celular</div><div>02 · Vitrine de produtos — 12 no total, 5 visíveis no desktop</div><div>03 · Mosaico com quatro banners</div><div>04 · Vitrine complementar — produtos selecionados</div></div><p style="margin:18px 0">O editor de quantidade, posição, imagens e publicação será desenvolvido na etapa de personalização. Esta tela apresenta a organização dos módulos.</p><a class="btn secondary" href="./index.html">Visualizar os módulos na home →</a>`);
else if(page==='sellers')content=panel('Empresas em análise',table(['Empresa fictícia','Cidade','Status'],[['Ateliê da Vila','Cianorte','Cadastro em análise'],['Casa Jardim','Maringá','Complementação necessária']]))+note('Aprovação comercial, classificação e habilitação financeira são processos separados. Uma loja por seller no início.');
else if(page==='aprovacao')content=pendingProductMarkup()+panel('Fila editorial demonstrativa',table(['Produto','Loja','Revisão'],[['Luminária de mesa','Casa Aurora','Descrição'],['Bolsa casual','Essencial Concept','Imagens'],['Vaso decorativo','Verde & Vida','Novo produto']]))+note('A publicação de uma revisão não pode restaurar preço ou estoque anteriores. Nenhuma aprovação real pode ser realizada neste protótipo.');
else if(page==='regras')content=panel('Regras comerciais e operacionais',table(['Regra','Definição'],[['Comissão','Uniforme, somente sobre produtos; percentual a definir'],['Frete','Por km de trajeto, proporcional, tarifa por seller'],['Transporte','Regra global por distância; parâmetros a definir'],['Despacho','Corte padrão 15h, ajustável para novas compras'],['Alto volume','Mais de 200 pedidos em um único dia'],['Pagamentos','Split, Pix e crédito; provedor a definir']])) ;
else if(page==='auditoria')content=empty('Registro de ações','Nenhuma ação administrativa real foi realizada. Na operação, este histórico registrará autor, data, escopo e motivo, com acesso autorizado.');
content=adminContent(page,role)??content;
document.querySelector('#portal').innerHTML=`<div class="utility"><div class="wrap"><span>PROTÓTIPO · Central atualizada em 21/10/2026 · Dados fictícios</span></div></div><header class="seller-header wrap"><a class="brand" href="./index.html">tem logo <strong>ali.</strong></a><div class="portal-areas"><span>Áreas da demonstração:</span><a href="./index.html">Comprador</a><a href="#seller">Vendedores</a><a href="#admin">Administração</a>${!isAdmin?'<button class="text-link" id="seller-logout">Sair da conta</button>':''}</div><button class="btn secondary portal-menu-button" aria-expanded="false" aria-controls="portal-sidebar">Abrir menu</button></header><div class="portal"><aside class="portal-sidebar" id="portal-sidebar"><h2>${isAdmin?'Administração':'Central de Vendedores'}</h2><p>${isAdmin?'Visão global do marketplace':(readMarketplace().stores.find(s=>s.id===sellerContext())?.name||'Loja')+' · Ambiente demonstrativo'}</p><nav aria-label="${isAdmin?'Administração':'Central de Vendedores'}">${menu.map(([id,label])=>`<a href="#${role}/${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="seller-note">${isAdmin?'Na operação real, acesso exclusivo à equipe autorizada.':'Acesso restrito à própria empresa na operação real.'}</div><a class="text-link" href="./index.html">← Voltar às compras</a></aside><main class="portal-main"><h1>${page==='inicio'?(isAdmin?'Um olhar sobre o marketplace':'Bem-vinda à sua central.'):title}</h1><p>${isAdmin?'Gestão global, revisão e acompanhamento da plataforma.':'Sua loja, sua equipe e sua operação em um só lugar. '+(sellerContext()!==0?'Contexto de loja selecionado pela administração.':'')}</p>${content}</main></div>`;
mountAdminContent(render,role);
if(page==='produtos')mountSellerProductList();if(page==='novo-produto'||page==='editar-produto')mountProductEditor(page==='editar-produto'?Number(itemId):null);
if(page==='pedidos'||page==='chat')mountOrderPanel(role,page);
document.querySelector('#seller-logout')?.addEventListener('click',()=>{sessionStorage.removeItem('temlogoali.seller-context');endSellerSession();location.hash='seller';render();window.scrollTo(0,0)});
document.querySelector('.portal-menu-button').onclick=e=>{const open=document.querySelector('.portal-sidebar').classList.toggle('open');e.target.setAttribute('aria-expanded',open);e.target.textContent=open?'Fechar menu':'Abrir menu'};
document.querySelectorAll('[data-demo-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();f.querySelector('.form-status').textContent='Simulação concluída. Nenhuma configuração foi gravada ou aplicada a uma loja real.'}));
document.title=`${title} · ${isAdmin?'Administração':'Central de Vendedores'}`;}
window.addEventListener('hashchange',render);render();



